import{_ as a,C as n,o as r,c as i,j as e,a as t,E as d,ao as l}from"./chunks/framework.ucUddl5u.js";const b=JSON.parse('{"title":"Running several agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md","lastUpdated":null}'),h={name:"guide/agents.md"};function c(p,s,g,u,w,k){const o=n("DemoLoop");return r(),i("div",null,[s[0]||(s[0]=e("h1",{id:"Running-several-agents",tabindex:"-1"},[t("Running several agents "),e("a",{class:"header-anchor",href:"#Running-several-agents","aria-label":'Permalink to "Running several agents {#Running-several-agents}"'},"​")],-1)),s[1]||(s[1]=e("p",null,[t("Ship of Tools is built for more than one agent at a time. Every session is a "),e("strong",null,"row"),t(" in Sessions mode: a project directory with its own Julia REPL and an agent pane running "),e("strong",null,"Claude Code"),t(", "),e("strong",null,"Codex"),t(", or a bare shell (see "),e("a",{href:"/ship-of-tools/dev/concepts/sessions#session-model"},"Hosts, sessions, REPLs"),t("). You move between rows from the keyboard, and each row's colour tells you whether it needs you.")],-1)),d(o,{name:"sessions",caption:"Demo session rows changing colour as a script sets their work states: green working, red waiting for your answer, purple waiting on a job, blue done, gray idle."}),s[2]||(s[2]=l(`<h2 id="Start-a-session" tabindex="-1">Start a session <a class="header-anchor" href="#Start-a-session" aria-label="Permalink to &quot;Start a session {#Start-a-session}&quot;">​</a></h2><p>Press <strong><code>s</code></strong> for Sessions mode and pick <strong><code>[+ create new]</code></strong>; the steps are in <a href="/ship-of-tools/dev/start/quickstart#start-session">Start an agent session</a>.</p><p>The daemon starts the agent in its own supervised <strong>capsule</strong>, so it keeps running when you switch rows, close the frontend, or lose the connection (see <a href="./../concepts/sessions">Sessions and persistence</a>).</p><h2 id="Move-between-sessions" tabindex="-1">Move between sessions <a class="header-anchor" href="#Move-between-sessions" aria-label="Permalink to &quot;Move between sessions {#Move-between-sessions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>s</code></td><td style="text-align:right;">Sessions mode — every row on every connected host, grouped by host</td></tr><tr><td style="text-align:right;"><code>Shift+ArrowRight</code> / <code>Shift+ArrowLeft</code></td><td style="text-align:right;">cycle the active session from anywhere</td></tr><tr><td style="text-align:right;"><code>Ctrl+Arrow</code></td><td style="text-align:right;">move focus between panes inside the session</td></tr></tbody></table><p>Switching rows is a frontend state change: it never restarts a session&#39;s REPL, so the REPL holding <code>x = 5</code> still holds it when you come back.</p><h2 id="Read-the-colours" tabindex="-1">Read the colours <a class="header-anchor" href="#Read-the-colours" aria-label="Permalink to &quot;Read the colours {#Read-the-colours}&quot;">​</a></h2><p>Each row is coloured by the agent&#39;s current work state — green while it works, red when it is blocked waiting for your answer, purple while it waits on a peer or a long job, blue when it has finished a turn you have not looked at, gray when idle. Scan the list instead of tabbing through each pane. See <a href="./../concepts/work-state">Work-state colours</a>.</p><h2 id="One-worktree-per-agent" tabindex="-1">One worktree per agent <a class="header-anchor" href="#One-worktree-per-agent" aria-label="Permalink to &quot;One worktree per agent {#One-worktree-per-agent}&quot;">​</a></h2><p>Parallel agents on one repository should not share a checkout. The bundled <code>worktree</code> skill (<code>/worktree</code> in a Claude Code session, backed by <code>comm-worktree-new.sh &lt;short&gt;</code>) creates a git worktree next to the repo and spawns a new session bound to it:</p><ul><li><p>directory <code>&lt;repo-parent&gt;/worktrees/&lt;repo&gt;-wt-&lt;short&gt;</code> (never inside the repo),</p></li><li><p>branch <code>wt/&lt;short&gt;</code> off the current <code>HEAD</code>,</p></li><li><p>a session labelled <code>&lt;repo&gt;-wt-&lt;short&gt;</code>, listed next to the parent row.</p></li></ul><p><code>/worktree status</code> shows the family and whether each worktree is ready to clean up, <code>/worktree sync</code> reminds the parent and worktree sessions to sync, and <code>/worktree clean</code> tears a finished one down. The same scripts (<code>comm-worktree-new.sh</code>, <code>-status.sh</code>, <code>-sync.sh</code>, <code>-clean.sh</code>) live in <code>~/.sot-comm/bin</code> for use from any shell.</p><h2 id="Hand-work-to-a-new-agent-in-another-repo" tabindex="-1">Hand work to a new agent in another repo <a class="header-anchor" href="#Hand-work-to-a-new-agent-in-another-repo" aria-label="Permalink to &quot;Hand work to a new agent in another repo {#Hand-work-to-a-new-agent-in-another-repo}&quot;">​</a></h2><p><code>comm-spawn.sh &lt;repo-path&gt; --task &quot;...&quot;</code> starts a new agent session on another package and has it report back to you over the comm relay. Combined with <a href="./messaging">agent messaging</a>, one session can fan work out to several others and collect their answers.</p><h2 id="A-separate-subscription-per-session" tabindex="-1">A separate subscription per session <a class="header-anchor" href="#A-separate-subscription-per-session" aria-label="Permalink to &quot;A separate subscription per session {#A-separate-subscription-per-session}&quot;">​</a></h2><p>A session normally runs under the agent&#39;s default login. To spend a different Claude subscription — a team account, say — create an account folder once outside Ship of Tools:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude-auth/team</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_CONFIG_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">~/.claude-auth/team</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> claude</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># then, inside that claude session: /login</span></span></code></pre></div><p>It then appears as a choice in the session picker (<code>Tab</code> cycles it), and rows running under it show a <code>· team</code> suffix. Ship of Tools discovers accounts; it never creates them or stores a credential. Details in <a href="/ship-of-tools/dev/guide/modes#Accounts">Modes</a>.</p>`,18))])}const f=a(h,[["render",c]]);export{b as __pageData,f as default};
